using Careersity.Application.Common.Exceptions; using Careersity.Domain.Courses; using Careersity.Domain.Enums; using Careersity.Domain.LearningResources; using FluentAssertions; using Microsoft.EntityFrameworkCore; using Xunit;
namespace Careersity.IntegrationTests.Persistence;
[Collection(PostgreSqlCollection.Name)]
public sealed class ExternalLearningPersistenceTests(PostgreSqlFixture fixture)
{
 [Fact]public async Task ProviderInstructorResourceAndAssignmentPersistWithReadableEnums(){var suffix=Guid.NewGuid().ToString("N");var provider=new LearningProvider("Provider",$"provider-{suffix}");provider.Publish();var instructor=new Instructor(provider.Id,"Teacher");instructor.Publish();var resource=new ExternalLearningResource(provider.Id,instructor.Id,"Lecture",ExternalResourceType.LectureVideo,ResourceAccessType.AuditFree,"https://example.com/lecture");resource.Publish();var course=new Course("Course",$"course-{suffix}","Description",CourseDifficulty.Beginner,30);var assignment=new CourseExternalResource(course.Id,resource.Id,0,true);await using(var db=fixture.CreateContext()){db.AddRange(provider,instructor,resource,course,assignment);await db.SaveChangesAsync();}await using var verify=fixture.CreateContext();(await verify.CourseExternalResources.SingleAsync(x=>x.Id==assignment.Id)).IsRequired.Should().BeTrue();var type=await verify.Database.SqlQuery<string>($"SELECT \"ResourceType\" AS \"Value\" FROM \"ExternalLearningResources\" WHERE \"Id\"={resource.Id}").SingleAsync();type.Should().Be("LectureVideo");}
 [Fact]public async Task UniqueProviderSlugAndCourseAssignmentConstraintsAreProtected(){var suffix=Guid.NewGuid().ToString("N");await using(var db=fixture.CreateContext()){db.LearningProviders.AddRange(new("One",$"same-{suffix}"),new("Two",$"same-{suffix}"));await db.Invoking(x=>x.SaveChangesAsync()).Should().ThrowAsync<ConflictException>();}var provider=new LearningProvider("Provider",$"unique-{suffix}");var resource=new ExternalLearningResource(provider.Id,null,"Reading",ExternalResourceType.Reading,ResourceAccessType.Free,"https://example.com");var course=new Course("Course",$"unique-course-{suffix}","Description",CourseDifficulty.Beginner,30);await using var relations=fixture.CreateContext();relations.AddRange(provider,resource,course,new CourseExternalResource(course.Id,resource.Id,0,true),new CourseExternalResource(course.Id,resource.Id,1,false));await relations.Invoking(x=>x.SaveChangesAsync()).Should().ThrowAsync<ConflictException>();}
}
